fn stop_task_request(request_id: &str, task: &str) -> String {
    let mut line = json!({
        "type": "control_request",
        "request_id": request_id,
        "request": { "subtype": "stop_task", "task_id": task },
    })
    .to_string();
    line.push('\n');
    line
}

