                    Err((old, err)) => {
                        // It stays as it was.
                        item.text = old_text;
                        item.images = old_images;
                        item.sent_from = old.anchor.sent_from.clone();
                        item.mode = old_mode;
                        item.saved = Some(old);
                        window.push_notification(
                            Notification::error(format!("{err:#}"))
                                .title("Could not save the queued prompt"),
                            cx,
                        );
                    }
                }
                this.auto_send_next(cx);
                cx.notify();
            });
        })
        .ok();
    })
    .detach();
}

