fn chain_on(
    &mut self,
    text: String,
    sending: Sending,
    chain_stamp: Option<u128>,
    cx: &mut Context<Self>,
) {
    let Sending::Now(
        mode,
        attached,
        sliced,
        code_task,
        sent_from,
        post_build_update,
        named_after,
    ) = sending
    else {
        return self.start(text, sending, cx);
    };
    let lanes = Lanes::of(Some(mode));
    let earlier_waits = chain_stamp.is_some_and(|stamp| {
        self.queue
            .iter()
            .any(|item| item.queued_at < stamp && Lanes::of(item.mode).overlaps(lanes))
            || self.chain_holds(lanes, stamp)
    });
    if !self.working.queues(mode) && !earlier_waits {
        self.next_chain_stamp = chain_stamp;
        let sending = Sending::Now(
            mode,
            attached,
            sliced,
            code_task,
            sent_from,
            post_build_update,
            named_after,
        );
        return self.start(text, sending, cx);
    }
    self.enqueue_at(
        match chain_stamp {
            Some(stamp) => QueuePlace::ChainSentAt(stamp),
            None => QueuePlace::Head,
        },
        text,
        false,
        mode,
        attached,
        sliced,
        code_task,
        sent_from,
        post_build_update,
        named_after,
        cx,
    );
}

/// Asks `text` straight away, beside any task the harness is working on,
/// in place of any question still open. It is saved apart from the
/// history, so it never becomes one of the tasks.
    let code_task = CodeTask {
        prompt: chain.text.to_string(),
        result: before.reply.final_output(),
    };
    let sending = Sending::Now(
        step.mode,
        Attached::default(),
        chain.sent.sliced,
        Some(code_task),
        Some(before.name.to_string()),
        false,
        Some(before.name.to_string()),
    );
    let stamp = chain.chain_stamp;
    self.pending_step = Some(PendingStep {
        added: (chain.name.to_string(), place),
        model: step.model,
        effort: step.effort,
    });
    self.chain_on(step.prompt, sending, stamp, cx);
    // Taken by the step as it is sent or queued.
    self.pending_step = None;
}

