                                .primary()
                                .small()
                                .label("Send code")
                                .on_click(cx.listener(|this, _, window, cx| this.send_code(window, cx))),
                        ),
                )
            })
            .child(
                div()
                    .id("login-status")
                    .text_sm()
                    .font_medium()
                    .whitespace_normal()
                    .when(build_failed, |this| this.text_color(theme.danger))
                    .child(status),

