            .iter()
            .map(|(_, ended, _)| *ended)
            .collect::<Option<Vec<_>>>()?
            .into_iter()
            .max()?
    };
    Some(Took {
        time: until.duration_since(started).unwrap_or_default(),
        approximate: spans.iter().any(|(_, _, approximate)| *approximate),
    })
}

