body='''/// A file as it was when the run began.
struct Kept {
    contents: Vec<u8>,
}

struct Snapshot {
    root: PathBuf,
    /// Folders inside the root that the run may change all the same: the
    /// location it works on, where that is inside this one, and the
    /// application's own data.
    exempt: Vec<PathBuf>,
    files: HashMap<PathBuf, Kept>,
    /// The folders under the root as it was taken.
    folders: HashSet<PathBuf>,
    /// The files the task itself changed there, each with how it last left
    /// it: its modification time and length, none where it removed it.
    touched: HashMap<PathBuf, Option<(SystemTime, u64)>>,
    /// The files the application itself saved there meanwhile, from the
    /// editor: the user's, never put back.
    saved: HashSet<PathBuf>,
}

impl Snapshot {
    fn take(root: PathBuf, exempt: Vec<PathBuf>) -> Self {
        let mut snapshot = Self {
            root,
            exempt,
            files: HashMap::new(),
            folders: HashSet::new(),
            touched: HashMap::new(),
            saved: HashSet::new(),
        };
        snapshot.folders = snapshot.listed_folders().into_iter().collect();
        for path in snapshot.listed() {
            if let Ok(contents) = std::fs::read(&path) {
                snapshot.files.insert(path, Kept { contents });
            }
        }
        snapshot
    }

    fn walk(&self) -> Vec<ignore::DirEntry> {
        if !self.root.is_dir() {
            return Vec::new();
        }
        let exempt = self.exempt.clone();
        ignore::WalkBuilder::new(&self.root)
            .hidden(false)
            .filter_entry(move |entry| {
                entry.file_name() != ".git" && !exempt.iter().any(|dir| entry.path() == dir)
            })
            .build()
            .filter_map(|entry| entry.ok())
            .collect()
    }

    /// The files under the root as the ProjectLocationsScope lists them,
    /// leaving out those exempt.
    fn listed(&self) -> Vec<PathBuf> {
        self.walk()
            .into_iter()
