                        .right(px(4.))
                        .min_w(px(14.))
                        .h(px(14.))
                        .px(px(3.))
                        .rounded_full()
                        .bg(accent)
                        .text_color(theme.accent_foreground)
                        .text_size(px(9.))
                        .flex()
                        .items_center()
                        .justify_center()
                        .child(uncommitted.to_string())
                        .into_any_element(),
                ),
