                    div()
                        .absolute()
                        .bottom(px(4.))
                        .right(px(4.))
                        .child(Spinner::new().xsmall())
                        .into_any_element(),
                ),
                LeftView::Run if started > self.run_seen => Some(
                    div()
                        .absolute()
                        .bottom(px(8.))
