    }

    /// Opens the task at `ix` in the right sidebar's Tasks tab, opening the
    /// sidebar first if it is closed, as the header's View all does.
    fn view_all(&mut self, ix: usize, window: &mut Window, cx: &mut Context<Self>) {
        if !self.refs_wanted() {
