    /// Follows what run `run`, of `agent`, reports, at `now`.
    pub fn follow(&mut self, run: usize, agent: Agent, event: &HarnessEvent, now: u64) {
        let Some(run) = self.runs.get_mut(run) else {
            return;
        };
        if !run.follow(event) {
