/// Creates `agent`'s volume where it isn't there, before it is first used,
/// so it is ready for the first login; mounted with `:U`, it is the
/// container user's to write. Blocking.
pub fn ensure_volume(agent: Agent) -> Result<()> {
    let output = podman_command()
        .args(["volume", "create", "--ignore", &home_volume(agent)])
        .stdin(Stdio::null())
        .output_logged()
        .context("could not run podman")?;
    if !output.status.success() {
        bail!(
            "podman couldn't create the volume {}: {}",
            home_volume(agent),
            String::from_utf8_lossy(&output.stderr).trim()
        );
    }
    Ok(())
}

/// Whether `agent` is logged in, in its own volume, using `image`: its
/// credentials file there and not empty, as the login view, the Welcome
/// check, and the settings all read it. Blocking.
pub fn logged_in(agent: Agent, image: &str, platform: Platform) -> Result<bool> {
    ensure_volume(agent)?;
    let file = format!("{HOME}/{}", credentials_file(agent));
    let args: Vec<OsString> = vec!["-s".into(), file.into()];
    let plan = bare(agent, RunKind::Question, platform);
    let output = podman_command()
        .args(plan.run_args(image, "test", &args, false))
        .stdin(Stdio::null())
        .output_logged()
        .context("could not run podman")?;
    match output.status.code() {
        Some(0) => Ok(true),
        Some(1) => Ok(false),
        // Podman failing to run the check isn't the harness logged out.
        code => match run_failure(code, &String::from_utf8_lossy(&output.stderr)) {
            Some(why) => bail!("{why}"),
            None => bail!(
                "couldn't read whether {} is logged in: {}",
                agent.label(),
                String::from_utf8_lossy(&output.stderr).trim()
            ),
        },
    }
}

/// The `podman` arguments that log `agent` in, in its volume, using
/// `image`: under a terminal where `tty`, with the port its login waits on
/// published.
pub fn login_args_for(agent: Agent, image: &str, platform: Platform, tty: bool) -> Vec<OsString> {
    let args: Vec<OsString> = login_args(agent).iter().map(Into::into).collect();
    let mut run =
        bare(agent, RunKind::Question, platform).run_args(image, agent.command(), &args, tty);
    if let Some(port) = callback_port(agent) {
        // Published just before the image, after `run`'s own options.
        let at = run.len() - args.len() - 2;
        run.insert(at, format!("127.0.0.1:{port}:{port}").into());
        run.insert(at, "-p".into());
    }
    run
}

