/// Podman or Docker, run through its own command and no other.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Runtime {
    Podman,
    Docker,
}

impl Runtime {
    /// Both, in the order Automatic tries them: Podman first, since it runs
    /// rootless on Linux.
    pub const ALL: [Runtime; 2] = [Runtime::Podman, Runtime::Docker];

    /// The command it runs through.
    pub fn command(self) -> &'static str {
        match self {
            Runtime::Podman => "podman",
            Runtime::Docker => "docker",
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Runtime::Podman => "Podman",
            Runtime::Docker => "Docker",
        }
    }

    /// Where to install it from on `platform`.
    pub fn install_url(self, platform: Platform) -> &'static str {
        match self {
            Runtime::Podman => platform.install_url(),
            Runtime::Docker => match platform {
                Platform::MacOs => "https://docs.docker.com/desktop/setup/install/mac-install/",
                Platform::Windows => "https://docs.docker.com/desktop/setup/install/windows-install/",
                Platform::Linux => "https://docs.docker.com/engine/install/",
            },
        }
    }

    /// What runs its containers on macOS and Windows: a Podman machine, or
    /// Docker Desktop.
    pub fn machine_label(self) -> &'static str {
        match self {
            Runtime::Podman => "Podman machine",
            Runtime::Docker => "Docker Desktop",
        }
    }
}

/// Which runtime the user picked in the settings: Automatic until another is
/// picked, remembered for the user, not for a project.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum RuntimeChoice {
    #[default]
    Automatic,
    Podman,
    Docker,
}

/// Where the user's choice of runtime is kept, in the per-user config
/// directory.
const RUNTIME_FILE: &str = "container-runtime";

impl RuntimeChoice {
    pub const ALL: [RuntimeChoice; 3] =
        [RuntimeChoice::Automatic, RuntimeChoice::Podman, RuntimeChoice::Docker];

    pub fn label(self) -> &'static str {
        match self {
            RuntimeChoice::Automatic => "Automatic",
            RuntimeChoice::Podman => "Podman",
            RuntimeChoice::Docker => "Docker",
        }
    }

    fn key(self) -> &'static str {
        match self {
            RuntimeChoice::Automatic => "automatic",
            RuntimeChoice::Podman => "podman",
            RuntimeChoice::Docker => "docker",
        }
    }

    fn file() -> Option<PathBuf> {
        if cfg!(test) {
            return None;
        }
        Some(dirs::config_dir()?.join("suspense").join(RUNTIME_FILE))
    }

    /// The user's choice, Automatic where none was made.
    pub fn load() -> Self {
        let Some(saved) = Self::file().and_then(|file| std::fs::read_to_string(file).ok()) else {
            return Self::default();
        };
        Self::ALL
            .into_iter()
            .find(|choice| choice.key() == saved.trim())
            .unwrap_or_default()
    }

    /// Keeps it as the user's choice.
    pub fn save(self) -> Result<()> {
        let Some(file) = Self::file() else {
            return Ok(());
        };
        if let Some(dir) = file.parent() {
            std::fs::create_dir_all(dir)?;
        }
        std::fs::write(file, self.key())?;
        Ok(())
    }
}

/// The runtime in use: 0 not yet worked out, Podman till it is; 1 Podman;
/// 2 Docker; 3 neither available.
static IN_USE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);

#[cfg(test)]
thread_local! {
    /// The runtime each test runs as, Podman unless it says otherwise.
    static TEST_RUNTIME: std::cell::Cell<Option<Runtime>> = const { std::cell::Cell::new(Some(Runtime::Podman)) };
}

/// Has this test run as `runtime`, its `podman` standing in for its command.
#[cfg(test)]
pub fn use_runtime_for_test(runtime: Option<Runtime>) {
    TEST_RUNTIME.set(runtime);
}

/// The runtime in use; none where neither is available.
pub fn runtime() -> Option<Runtime> {
    #[cfg(test)]
    return TEST_RUNTIME.get();
    #[cfg(not(test))]
    match IN_USE.load(std::sync::atomic::Ordering::SeqCst) {
        2 => Some(Runtime::Docker),
        3 => None,
        _ => Some(Runtime::Podman),
    }
}

/// Uses `runtime` from the next run on.
pub fn set_runtime(runtime: Option<Runtime>) {
    let value = match runtime {
        Some(Runtime::Podman) => 1,
        Some(Runtime::Docker) => 2,
        None => 3,
    };
    IN_USE.store(value, std::sync::atomic::Ordering::SeqCst);
}

/// The runtime in use, or Podman where none is, for what to name.
pub fn runtime_label() -> &'static str {
    runtime().unwrap_or(Runtime::Podman).label()
}

/// The runtime `choice` picks, as the ContainerEnvironmentScope's choosing
/// says: one picked by hand, whether or not it works; for Automatic, the
/// first that is installed and can run a container, none where neither
/// can. Blocking.
pub fn pick_runtime(choice: RuntimeChoice, platform: Platform) -> Option<Runtime> {
    match choice {
        RuntimeChoice::Podman => Some(Runtime::Podman),
        RuntimeChoice::Docker => Some(Runtime::Docker),
        RuntimeChoice::Automatic => Runtime::ALL.into_iter().find(|&runtime| {
            matches!(state_of(runtime, platform), PodmanState::Ready(_)) && access_of(runtime).is_ok()
        }),
    }
}

/// Works out the runtime in use anew, from the user's choice, and uses it
/// from the next run on. Blocking.
pub fn refresh_runtime() -> Option<Runtime> {
    #[cfg(test)]
    return runtime();
    #[cfg(not(test))]
    {
        let picked = pick_runtime(RuntimeChoice::load(), Platform::current());
        set_runtime(picked);
        picked
    }
}

