#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ResourceKind {
    Container,
    Image,
    Volume,
}

/// A container, image, or volume the application made, in `runtime`.
#[derive(Clone, Debug, PartialEq)]
pub struct Resource {
    pub runtime: Runtime,
    pub kind: ResourceKind,
    /// What deletes it: its id, or a volume's name.
    pub id: String,
    pub name: String,
    /// What it is for, as "Default image" or "Codex login".
    pub purpose: String,
    /// How much disk it takes, in bytes, where the runtime says.
    pub size: Option<u64>,
    /// When it was made, as the runtime gives it.
    pub created: Option<String>,
}

impl Resource {
    /// What deleting it loses, as its confirmation says.
    pub fn loses(&self) -> String {
        match self.kind {
            ResourceKind::Container => format!(
                "{}: the task or question running in it is stopped, as cancelling stops it.",
                self.name
            ),
            ResourceKind::Image => format!("{}: it is built again when next needed.", self.name),
            ResourceKind::Volume => format!(
                "{}: the harness must log in again.",
                self.name
            ),
        }
    }
}

/// Reads a size as a runtime prints it, "1.23 GB", "512MB", or "0B (virtual
/// 1.2GB)", in bytes.
fn bytes_in(printed: &str) -> Option<u64> {
    let first = printed.split('(').next()?.trim().replace(' ', "");
    let split = first.find(|c: char| c.is_ascii_alphabetic())?;
    let (number, unit) = first.split_at(split);
    let number: f64 = number.parse().ok()?;
    let scale = match unit.to_ascii_lowercase().as_str() {
        "b" => 1.,
        "kb" | "kib" => 1e3,
        "mb" | "mib" => 1e6,
        "gb" | "gib" => 1e9,
        "tb" | "tib" => 1e12,
        _ => return None,
    };
    Some((number * scale) as u64)
}

/// A size as shown, "1.2 GB".
pub fn size_label(bytes: u64) -> String {
    let bytes = bytes as f64;
    for (scale, unit) in [(1e12, "TB"), (1e9, "GB"), (1e6, "MB"), (1e3, "kB")] {
        if bytes >= scale {
            return format!("{:.1} {unit}", bytes / scale);
        }
    }
    format!("{bytes:.0} B")
}

/// How long ago `created`, as a runtime gives it, "2026-10-12 10:00:00
/// +0700 +07", was, as "3 days ago".
pub fn age_label(created: &str) -> Option<String> {
    let mut parts = created.split_whitespace();
    let (date, time, zone) = (parts.next()?, parts.next()?, parts.next()?);
    let time = time.split('.').next()?;
    let at = chrono::DateTime::parse_from_str(&format!("{date} {time} {zone}"), "%Y-%m-%d %H:%M:%S %z").ok()?;
    let ago = chrono::Utc::now().signed_duration_since(at);
    let (n, unit) = if ago.num_days() >= 1 {
        (ago.num_days(), "day")
    } else if ago.num_hours() >= 1 {
        (ago.num_hours(), "hour")
    } else if ago.num_minutes() >= 1 {
        (ago.num_minutes(), "minute")
    } else {
        return Some("just now".into());
    };
    Some(format!("{n} {unit}{} ago", if n == 1 { "" } else { "s" }))
}

/// Whether `name`, as a runtime lists it, is one the application gave:
/// beginning `suspense-`, wherever its registry says it is.
fn named_ours(name: &str) -> bool {
    name.rsplit('/').next().is_some_and(|name| name.starts_with("suspense-"))
}

/// What an image of the application's named `repository` is for.
fn image_purpose(repository: &str) -> String {
    let name = repository.rsplit('/').next().unwrap_or(repository);
    match name.strip_prefix("suspense-project-") {
        Some(key) => {
            // Its key is the project's folder and a hash of where it is.
            let project = key.rsplit_once('-').map_or(key, |(project, _)| project);
            format!("Project image · {project}")
        }
        None => "Default image".into(),
