    pub fn confirm_delete(&mut self, path: PathBuf, window: &mut Window, cx: &mut Context<Self>) {
        let name = path
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_else(|| path.display().to_string());
        let description = if path.is_dir() {
            "This can't be undone. Everything in the folder is deleted too."
        } else {
            "This can't be undone."
        };
        let this = cx.entity().downgrade();
        window.open_alert_dialog(cx, move |alert, _, _| {
            let (this, path) = (this.clone(), path.clone());
            alert
                .title(SharedString::from(format!("Delete {name}?")))
                .description(description)
                .button_props(
                    DialogButtonProps::default()
                        .ok_text("Delete")
                        .ok_variant(ButtonVariant::Danger)
                        .show_cancel(true),
                )
                .on_ok(move |_, window, cx| {
                    this.update(cx, |this, cx| this.delete(path.clone(), window, cx))
                        .ok();
                    true
                })
        });
    }

    /// Deletes `path` from disk for good, or says why it couldn't.
    pub fn delete(&mut self, path: PathBuf, window: &mut Window, cx: &mut Context<Self>) {
        let deleted = if path.is_dir() {
            std::fs::remove_dir_all(&path)
        } else {
            std::fs::remove_file(&path)
        };
        match deleted {
            Ok(()) => {
                cx.emit(EntryMoved {
                    from: path.clone(),
                    to: None,
                });
                if let Some(dir) = path.parent() {
                    self.load(dir.to_path_buf(), cx);
                }
            }
            Err(err) => window.push_notification(
                Notification::error(format!("{err}")).title("Could not delete"),
                cx,
            ),
        }
/// The "Harness" group of radio buttons beneath the agents: one per agent
/// checked, in their order, each with its command muted beside it and "Not
/// installed" where it can't be found, `picked` picked.
pub fn harness_group<T: 'static>(
    id: &'static str,
    agents: &[Agent],
    picked: Agent,
    pick: fn(&mut T, Agent),
    cx: &mut Context<T>,
) -> AnyElement {
    let muted = cx.theme().muted_foreground;
    let mono = cx.theme().mono_font_family.clone();
    let rows: Vec<AnyElement> = Agent::ALL
        .into_iter()
        .filter(|agent| agents.contains(agent))
        .map(|agent| {
            h_flex()
                .gap_2()
                .child(
                    Radio::new(SharedString::from(format!("{id}-{}", agent.command())))
                        .label(agent.label())
                        .checked(agent == picked)
                        .on_click(cx.listener(move |this, _: &bool, _, cx| {
                            pick(this, agent);
                            cx.notify();
                        })),
                )
                .child(div().text_sm().text_color(muted).font_family(mono.clone()).child(agent.command()))
                .when(!agent.installed(), |row| {
                    row.child(div().text_sm().text_color(muted).child("Not installed"))
                })
                .into_any_element()
        })
        .collect();
    v_flex()
        .id(id)
        .gap_1p5()
        .child(div().text_sm().font_medium().child("Harness"))
        .children(rows)
        .into_any_element()
}

